{
  "reviews": [
    {
      "benchmark": "arc",
      "instrument_review": "Condition-native review of ARC-AGI-2 public test problems, inspected official scoring software and ARC Prize verified-testing rules. Only the supplied passage supports this review. EFPA sections and item IDs are retained; human-testing concepts are explicitly qualified. Section ratings are judgements about available evidence, not an aggregate quality score.",
      "supported_claims": [
        {
          "ids": ["1"],
          "finding": "Instrument: ARC-AGI-2. Developers: ARC Prize Foundation staff and partners; individual authorship is not established. The passage attributes the technical report's Figure 1 to François Chollet and colleagues. Sources were inspected on 7 October 2026."
        },
        {
          "ids": ["2.1", "2.2", "2.3", "2.5"],
          "finding": "Domain keywords: rule inference, unfamiliar grid problems, reasoning. Area: AI evaluation. Intended assessed population: AI systems. One overall task-performance score is described; no separate scores established as distinct skills."
        },
        {
          "ids": ["2.6", "2.8", "2.9", "2.10"],
          "finding": "AI systems produce coloured output grids from worked grid pairs and new inputs. Responses are generated outputs; stimuli are two-dimensional coloured grids. Verified testing specifies settings, a spending limit and one run."
        },
        {
          "ids": ["2.11", "2.15", "2.16"],
          "finding": "There are 1,000 development problems and three fixed evaluation sets of 120 problems: public, semi-private and private. Problems can contain multiple new inputs. Sets were matched for human difficulty; AI equivalence is not established. ARC-AGI-1 and ARC-AGI-2 are separate versions."
        },
        {
          "ids": ["2.17", "3.1", "3.2", "3.3", "3.4"],
          "finding": "The assessed AI supplies outputs for digital scoring. Two attempts are permitted per input. Credit requires exact size and colour matches. Input credits are averaged within each problem, then problem scores are averaged. Scores are unstandardised performance proportions; standard-score transformation is not applicable."
        },
        {
          "ids": ["5.1", "5.2"],
          "finding": "Available materials include public problems, a technical report, testing rules, running software, marking tests and a dated change record. Public data use Apache 2.0. Hidden-data rules address confidentiality, provider handling and selected-submission code review."
        },
        {
          "ids": ["general_description"],
          "finding": "ARC-AGI-2 evaluates AI systems on inferring transformations from example grid pairs and producing exact outputs for unfamiliar inputs. Its stated purpose is comparing performance on these problems while investigating broader reasoning claims. Public development materials support practice; evaluation sets have differing access restrictions. Human solving informed selection and difficulty matching, but does not establish AI score precision or general intelligence measurement. Verified evaluations use specified settings, spending limits and one run. Public scoring awards partial problem credit when some new inputs are solved, while requiring each credited grid to match completely."
        },
        {
          "ids": ["6.1.1"],
          "rating": 2,
          "finding": "The passage gives an adequate task-level rationale linking example-based rule inference to unfamiliar problem solving. Broader intelligence interpretations lack comparable support."
        },
        {
          "ids": ["6.1.3.1", "6.1.3.2"],
          "rating": 2,
          "finding": "Grid format, low specialist-knowledge aims, compositional demands, human piloting and developer review give a basic design and content-development rationale."
        },
        {
          "ids": ["6.2.1"],
          "rating": 2,
          "finding": "The intended task and reason for constructing it are explained sufficiently for a limited grid-performance interpretation."
        },
        {
          "ids": ["6.2.2"],
          "rating": 2,
          "finding": "Item sources, human piloting, repeated-rule removal and subsequent corrections are described, although full development analyses are unavailable."
        },
        {
          "ids": ["6.2.4"],
          "rating": 2,
          "finding": "Verified-testing conditions include specified settings, spending limits and one-run use; complete operational details are not reproduced."
        },
        {
          "ids": ["6.2.13"],
          "rating": 2,
          "finding": "The supplied description uses understandable language without evident discriminatory wording. This rating covers the passage, not all original documentation."
        },
        {
          "ids": ["6.3.2"],
          "rating": 2,
          "finding": "Exact-match rules and within-problem averaging are explicit. Inspected marking tests address correct answers, wrong sizes, changed squares and missing outputs."
        },
        {
          "ids": ["6.3.4", "6.3.7"],
          "rating": 2,
          "finding": "The passage distinguishes partial problem credit from fully solved problems, limits interpretation to grid tasks, and describes development/evaluation separation and restrictions on repeated verified feedback."
        },
        {
          "ids": ["6.3.9"],
          "rating": 2,
          "finding": "Relevant supporting material types are identified, including the technical report, rules, software and change record; full bibliographic references are not supplied."
        },
        {
          "ids": ["6.2.14", "6.3.10", "6.4"],
          "rating": 2,
          "finding": "Available explanations adequately support a limited description and interpretation of grid-task evaluation. These section judgements do not establish adequacy for broader intelligence claims."
        }
      ],
      "documented_problems": [
        {
          "ids": ["6.1.3.3", "7.1.7"],
          "finding": "Post-release corrections include coloured squares and unclear examples. This establishes some material defects, but not their prevalence or the quality of the current complete set."
        },
        {
          "ids": ["3.2", "6.3.4"],
          "finding": "Software awards fractional problem credit, whereas published instructions reserve 'fully solved' for all inputs being correct. Results require explicit identification of which meaning is used."
        },
        {
          "ids": ["8.3.2.1", "9.4", "10.5"],
          "finding": "The change record does not recalculate every affected AI score. Comparisons across corrected materials therefore need version-specific interpretation."
        },
        {
          "ids": ["9.3", "9.7"],
          "finding": "Verified testing uses one run. Human difficulty matching addresses set selection, not variation in repeated AI scores."
        },
        {
          "ids": ["10.4", "11.1.2"],
          "finding": "Public evaluation problems are accessible, and hidden-data handling acknowledges possible escape. Exposure safeguards do not establish absence of prior exposure."
        },
        {
          "ids": ["10.5"],
          "finding": "The supplied studies concern two-dimensional grid problems. Broader reasoning and intelligence claims extend beyond the demonstrated task domain; their validity remains unresolved."
        }
      ],
      "missing_information": [
        {
          "ids": ["1"],
          "finding": "Reviewer name, current review date, previous review, complete original authors, publisher/distributor identity as distinct from developer, original publication date and current edition date are not supplied. Local-version name, local adaptation authors, adaptation publisher and adaptation date have no identified adaptation to describe."
        },
        {
          "ids": ["2.4"],
          "finding": "Supplier-defined intended users are not explicitly stated; researcher access does not establish a formal user classification."
        },
        {
          "ids": ["2.7"],
          "finding": "AI prerequisites for command of any instruction language, language fluency, reading and writing are not specified. Attention and digital skills require an AI-specific operational definition before classification. Human physical requirements are addressed under reinterpretations."
        },
        {
          "ids": ["2.11"],
          "finding": "Minimum, maximum and typical numbers of new input grids per problem, and corresponding total scoring opportunities, are not provided."
        },
        {
          "ids": ["2.12.1", "2.12.2", "2.13"],
          "finding": "Individual/group administration and the original supervision categories are not directly specified for AI execution. Required devices, connectivity and computing arrangements are not fully stated; verified rules do provide some execution control."
        },
        {
          "ids": ["2.14"],
          "finding": "Administrator preparation, administration, scoring, analysis and feedback times are absent. Digital scoring alone does not establish zero time for every associated activity."
        },
        {
          "ids": ["3.5", "8.1.4"],
          "finding": "No differentiated norms or norm-sampling procedure are described. Human development-study selection is not an AI norm sample."
        },
        {
          "ids": ["4.1", "4.2", "4.3", "4.4", "4.5", "4.6", "4.7", "4.8", "4.9", "4.10"],
          "finding": "ARC Prize says it releases outputs, costs, times and problem scores, but the complete archive was not checked. Availability and number of EFPA-style interpretive reports, names, presentation, structure, context sensitivity, development, modifiability, transparency, content and recipients are not established."
        },
        {
          "ids": ["5.3"],
          "finding": "Supplier-required test-use qualifications are unknown; absence of requirements in the passage does not mean none exist."
        },
        {
          "ids": ["6.1.2"],
          "rating": 0,
          "finding": "Human piloting is described, but a sufficient synthesis of empirical research supporting the proposed reasoning construct is not supplied."
        },
        {
          "ids": ["6.1.3.3"],
          "rating": 0,
          "finding": "Repeated-rule removal and human difficulty selection are reported, but final-item decision criteria, item-level analyses and their results are insufficiently detailed."
        },
        {
          "ids": ["6.1.5"],
          "finding": "Psychometric framework is not specified. Human difficulty information informed selection, but item difficulty values, means, standard deviations, discrimination, item-total correlations, IRT parameters, distractor results and DIF indices are not provided."
        },
        {
          "ids": ["6.1.6", "6.1.7", "6.1.8"],
          "rating": 0,
          "finding": "Item-analysis methods and final-set results are insufficient to judge methodology, psychometric item quality or overall development quality."
        },
        {
          "ids": ["6.2.5", "6.2.6", "6.2.7", "6.2.8", "6.2.9", "6.2.10", "6.2.11", "6.2.12"],
          "rating": 0,
          "finding": "Documentation is insufficient to evaluate coverage of norms, precision, formal content validation, internal structure, external relationships, other validation, fair use or digitally generated interpretive reports. Report availability and norm applicability remain uncertain."
        },
        {
          "ids": ["6.3.1", "6.3.8"],
          "rating": 0,
          "finding": "Complete step-by-step administration, error handling, hardware/software requirements and technical-support guidance are not supplied."
        },
        {
          "ids": ["6.3.3", "6.3.6"],
          "rating": 0,
          "finding": "Norming instructions and AI-specific fairness/bias procedures are not established. Norming may be unnecessary for an explicitly restricted raw-score comparison purpose, but that restriction is not documented."
        },
        {
          "ids": ["7.1.1", "7.1.2", "7.1.3", "7.1.4", "7.1.5", "7.1.7", "7.1.8"],
          "rating": 0,
          "finding": "Public software and examples establish inspectability, but do not supply enough evidence to rate operational robustness, task comprehensibility for assessed systems, complete instructions, response entry, interface, current item-content quality or overall digital materials."
        },
        {
          "ids": ["8.1.1", "8.1.2", "8.1.3.1", "8.1.3.2", "8.1.3.3"],
          "rating": 0,
          "finding": "No AI norming application or reference population is established. Local relevance, representativeness, classical norm sample size, continuous norm sample size and modelling therefore cannot be rated; applicability is unresolved."
        },
        {
          "ids": ["8.2.1.1", "8.2.1.2", "8.2.1.5", "8.2.2"],
          "rating": 0,
          "finding": "No critical-score interpretation is established. Standard-setting judge selection/training, judge count, agreement and empirical cut-score validation are unknown. Puzzle review is not evidence of standard setting."
        },
        {
          "ids": ["8.2.1.3", "8.2.1.4"],
          "finding": "No standard-setting procedure or agreement-computation method is reported."
        },
        {
          "ids": ["8.3.1", "8.3.2.1", "8.3.3"],
          "rating": 0,
          "finding": "Norm collection dates, norm adequacy checks and acceptable norms are not established. No norm-age rating can be inferred from source-inspection dates. Overall norm applicability remains unresolved."
        },
        {
          "ids": ["8.3.2", "8.3.2.2", "8.3.2.3"],
          "finding": "Neither acceptable AI norms nor an explicit sole-purpose exception under EFPA's raw-ranking guidance is established. Norm-based fair-use information and updating history are absent."
        },
        {
          "ids": ["9.1"],
          "finding": "No AI reliability coefficients, standard errors, subgroup estimates or estimates for norm groups are supplied."
        },
        {
          "ids": ["9.2.1", "9.2.3"],
          "rating": 0,
          "finding": "Internal-consistency studies, sample sizes and coefficients are absent. Suitability for this task collection requires justification."
        },
        {
          "ids": ["9.2.2", "9.2.4"],
          "finding": "No internal-consistency coefficient type or sample-match information is supplied."
        },
        {
          "ids": ["9.3.1", "9.3.2"],
          "rating": 0,
          "finding": "No identical-condition AI retest study, sample size or stability coefficient is supplied."
        },
        {
          "ids": ["9.3.3", "9.3.4"],
          "finding": "Retest intervals and matching of retest samples to intended AI systems are unknown."
        },
        {
          "ids": ["9.4.1", "9.4.2"],
          "rating": 0,
          "finding": "Human difficulty matching does not provide AI alternate-form sample sizes or equivalence coefficients."
        },
        {
          "ids": ["9.4.3"],
          "finding": "No AI equivalence-study sample or sample-match evidence is given."
        },
        {
          "ids": ["9.5.1", "9.5.3"],
          "rating": 0,
          "finding": "No IRT precision study, sample size or coefficient/information-function results are supplied; IRT applicability is unestablished."
        },
        {
          "ids": ["9.5.2"],
          "finding": "No latent-trait reliability, rho, information function or conditional standard error is reported."
        },
        {
          "ids": ["9.7.1", "9.7.3", "9.8"],
          "rating": 0,
          "finding": "No adequate alternative precision study, sample size, score uncertainty or repeated-run result is supplied. Overall precision is unrateable from this passage."
        },
        {
          "ids": ["9.7.2"],
          "finding": "No alternative precision-estimation method is described. Marking unit tests check scoring behaviour, not score precision across replications."
        },
        {
          "ids": ["10.1"],
          "finding": "Content arguments are considered under section 6 as EFPA directs. Expert validation procedures and evidence of domain coverage are insufficient for broad reasoning interpretations."
        },
        {
          "ids": ["10.2.1"],
          "finding": "No EFA, CFA, structural-invariance, DIF or other dimensionality technique is reported."
        },
        {
          "ids": ["10.2.2", "10.2.3"],
          "rating": 0,
          "finding": "No evidence establishes the proposed score structure or invariance/DIF across relevant AI groups."
        },
        {
          "ids": ["10.3.1.1"],
          "finding": "A human background-factor analysis is described, but no AI convergent/discriminant or experimental validation design is established."
        },
        {
          "ids": ["10.3.1.2", "10.3.1.3", "10.3.1.4", "10.3.1.5", "10.3.1.6", "10.3.1.7", "10.3.1.8", "10.3.1.9", "10.3.1.11"],
          "rating": 0,
          "finding": "Expected AI group differences, convergent/discriminant correlations, MTMM results, experimental or other external-variable validation, adequate validation sample sizes and marker quality are not established. Applicability of optional designs is unresolved; the human development study cannot supply these AI conclusions."
        },
        {
          "ids": ["10.3.1.10"],
          "finding": "Dates of relevant external-variable validation studies are not supplied."
        },
        {
          "ids": ["10.3.2.1"],
          "finding": "No predictive, concurrent or postdictive external-criterion study is supplied."
        },
        {
          "ids": ["10.3.2.2", "10.3.2.3", "10.3.2.4", "10.3.2.7"],
          "rating": 0,
          "finding": "External-criterion study samples, criterion quality, relationship strength and overall criterion evidence are absent, including prediction of language, social or real-world work performance."
        },
        {
          "ids": ["10.3.2.6"],
          "finding": "External-criterion study age is unknown."
        },
        {
          "ids": ["10.4.1"],
          "finding": "Design measures address repeated rules, program search and exposure. They suggest relevant response-process and unintended-consequence questions, without establishing a completed validation paradigm."
        },
        {
          "ids": ["10.4.2", "10.4.3"],
          "rating": 0,
          "finding": "Study adequacy and results excluding unintended solution routes or exposure effects are insufficiently documented."
        },
        {
          "ids": ["10.5"],
          "rating": 0,
          "finding": "Task content is relevant to grid-rule inference, but evidence is insufficient to judge validity of broader reasoning interpretations or generalisation. This is uncertainty, not demonstrated invalidity."
        },
        {
          "ids": ["11.1.1", "11.1.2", "11.2", "11.3", "11.4", "11.5", "11.6.1", "11.6.2", "11.7", "11.8"],
          "rating": 0,
          "finding": "AI-specific construct relevance across groups, inclusive documentation/design, subgroup piloting, comparable precision, differential validity, norm/cut-score fairness and report fairness are not established. Human background findings do not establish these properties for AI systems. Norm, criterion and report branches have unresolved applicability."
        },
        {
          "ids": ["12.1", "12.2", "12.3", "12.4", "12.5", "12.6", "12.7"],
          "rating": 0,
          "finding": "No three score-linked interpretive report examples are supplied. Report scope, consistency, validity, bias, recipient acceptability, detail and overall adequacy cannot be judged. Applicability is unresolved because released score records are not necessarily interpretive reports."
        },
        {
          "ids": ["final_evaluation", "conclusions"],
          "finding": "Grid-task comparisons are the supported scope. Precision and validity are critical for interpreting small differences or broader reasoning claims; both receive 0 because evidence is insufficient. Under EFPA guidance, those uses should be restricted to research or exceptional use by highly skilled experts. Required expertise includes interpreting scoring, versions, exposure and execution conditions; agreement with supplier qualification requirements is unknown. Future validation plans are not supplied."
        },
        {
          "ids": ["summary_of_ratings"],
          "finding": "Section ratings: 6.4=2; 7.1.8=0; 7.2.7=n/a; 8.3.3=0 with applicability unresolved; 9.8=0; 10.5=0; 11.8=0; 12.7=0 with applicability unresolved. No aggregate score is calculated."
        }
      ],
      "reinterpretations": [
        {
          "ids": ["instrument_scope"],
          "finding": "EFPA is applied to an AI benchmark by treating the AI system under specified execution conditions as the assessed entity, benchmark problems as items, and evaluators as test users. This does not establish that AI scores measure human psychological constructs."
        },
        {
          "ids": ["rating_key"],
          "finding": "Original scale retained: n/a=not applicable; 0=insufficient information; 1=inadequate; 2=adequate; 3=good; 4=excellent. Unknown conditional applicability receives a provisional 0 with explanation. Missing evidence is not a rating of 1."
        },
        {
          "ids": ["2.7"],
          "finding": "Human handedness, hearing and motor capabilities are n/a. Human vision is n/a; machine access to grid representations remains relevant but insufficiently described. Human reading/writing and attention are not assumed equivalent to AI processing."
        },
        {
          "ids": ["2.12.1", "2.12.2", "2.17"],
          "finding": "Administration categories are considered as controls over system identity, configuration and execution. AI-generated answers are direct task responses, not human self-report or informant testimony."
        },
        {
          "ids": ["6.1.4", "6.2.3"],
          "rating": "n/a",
          "finding": "No translated or local adaptation is identified. ARC-AGI-1 versus ARC-AGI-2 is a version distinction, not evidence of translation equivalence."
        },
        {
          "ids": ["6.3.5"],
          "rating": "n/a",
          "finding": "Human test-taker debriefing does not apply to the assessed AI. Guidance for communicating results to human stakeholders remains relevant but is not supplied."
        },
        {
          "ids": ["7.1.6"],
          "rating": "n/a",
          "finding": "Human disability accessibility of the assessed AI is inapplicable. Human operator accessibility and AI input compatibility would require separate evidence."
        },
        {
          "ids": ["7.2.1", "7.2.2", "7.2.3", "7.2.4", "7.2.5", "7.2.6", "7.2.7"],
          "rating": "n/a",
          "finding": "The described assessment uses digital grids and software; no paper or other non-digital administration is identified."
        },
        {
          "ids": ["8", "9", "10", "11"],
          "finding": "Human sample-size, demographic, norm-age and coefficient guidance is not automatically transferred to task counts or AI populations. Human participant counts describe development evidence. AI subgroup fairness would require justified groups and comparable access, exposure and execution conditions."
        },
        {
          "ids": ["9.6.1", "9.6.2", "9.6.3"],
          "rating": "n/a",
          "finding": "Described operational scoring is an exact comparison without judgement. Agreement among developers selecting puzzles is a separate development question."
        },
        {
          "ids": ["10.3.2.5"],
          "rating": "n/a",
          "finding": "No diagnostic use or qualitative external-criterion classification is stated. Exact-answer accuracy is not a diagnostic-validity coefficient."
        },
        {
          "ids": ["12", "summary_of_ratings"],
          "finding": "Score records are distinguished from interpretive reports. The supplied model's summary references 7.2.8, but the actual non-digital overall item is 7.2.7; that item is retained."
        },
        {
          "ids": ["part_C"],
          "finding": "Instrument source: supplied ARC-AGI-2 passage only. Review framework: EFPA (2025), Model for the Review, Description and Evaluation of Psychological and Educational Tests, version 5.0, supplied extraction, CC BY-SA 4.0, https://www.efpa.eu/. Referenced underlying benchmark materials were not independently consulted. No numbered item omissions."
        }
      ],
      "closing_note": "Unclear questions/instructions: 'fully solved' differs from the software's fractional problem score; comparison conditions outside verified testing, AI prerequisites and the intended scope of broader reasoning claims need clarification."
    },
    {
      "benchmark": "designqa",
      "instrument_review": "Condition-native review of the original DesignQA benchmark described in the 2024 paper and its public scoring software. Only the supplied passage supports this review. EFPA sections and item IDs are retained; human-testing concepts are explicitly qualified. Section ratings are evidence judgements, not an aggregate quality score.",
      "supported_claims": [
        {
          "ids": ["1"],
          "finding": "Instrument: DesignQA, original benchmark described in a 2024 paper. Developers are described as researchers and engineers working with Formula SAE materials. Sources were inspected on 6 October 2026."
        },
        {
          "ids": ["2.1", "2.2", "2.3", "2.5"],
          "finding": "Domain keywords: engineering-rule retrieval, drawing understanding, rule application. Area: AI engineering-document evaluation. Assessed population: AI systems. Six task-group scores and an equally weighted overall score are described; distinct latent skills are not established."
        },
        {
          "ids": ["2.6", "2.8", "2.9", "2.10"],
          "finding": "AI systems receive written rules, images or drawings and produce text or yes/no answers, sometimes explanations. Inputs and information supply vary: some systems receive a whole rulebook, others retrieved passages. Instructions and settings are described in the paper."
        },
        {
          "ids": ["2.11", "2.16"],
          "finding": "The paper reports 1,451 question-answer pairs across six fixed task groups: individual-rule retrieval, related-rule retrieval, terminology, component presence, dimensions and performance. Individual-rule retrieval has 1,192 questions; performance has 16. Input variants were also studied; score-adaptive item selection is not described."
        },
        {
          "ids": ["2.17", "3.1", "3.2", "3.3", "3.4"],
          "finding": "The AI supplies responses for digital scoring. Marking combines supplied-answer text similarity and yes/no accuracy, sometimes with explanation similarity. Six group scores receive equal overall weight. These are unstandardised performance metrics; no standard-score transformation is described."
        },
        {
          "ids": ["5.1", "5.2"],
          "finding": "Public materials include questions, instructions, scoring code and some AI responses, with a supporting paper and identifiable code history."
        },
        {
          "ids": ["general_description"],
          "finding": "DesignQA compares AI systems on questions grounded in Formula SAE engineering materials. Its six task groups cover finding rules, explaining terms, identifying components, checking dimensions and assessing performance requirements. Questions use text and vehicle images or drawings, with text and yes/no responses. The reported 1,451 pairs are unevenly distributed across groups. Public software combines different marking methods and equally weights the six group scores. Results reflect both the AI and its supplied information. The passage supports use as an examination of these tasks under stated conditions; transfer to other documents or engineering projects remains uncertain."
        },
        {
          "ids": ["6.1.1", "6.1.3.1", "6.1.3.2"],
          "rating": 2,
          "finding": "Practical engineering activities motivate the task types, and real rules, designs and test data inform content. This adequately motivates the narrow task domain, with limited breadth."
        },
        {
          "ids": ["6.2.1", "6.2.2"],
          "rating": 2,
          "finding": "The passage explains the task rationale, source materials, practitioner contributions and review process, while acknowledging review exceptions and restricted coverage."
        },
        {
          "ids": ["6.2.7"],
          "rating": 2,
          "finding": "Content-documentation coverage identifies practical sources and reviewer checks, including their limits. This does not establish comprehensive content validity."
        },
        {
          "ids": ["6.2.13"],
          "rating": 2,
          "finding": "The supplied description uses understandable language without evident discriminatory wording. Original documentation as a whole was not examined."
        },
        {
          "ids": ["6.3.4"],
          "rating": 2,
          "finding": "Interpretive cautions identify restricted domain coverage, imperfect marking, information-supply differences and uncertainty when transferring to another technical document."
        },
        {
          "ids": ["6.3.9"],
          "rating": 2,
          "finding": "A supporting 2024 paper, public instructions, questions and scoring software are identified, although complete bibliographic details are absent."
        },
        {
          "ids": ["6.2.14"],
          "rating": 2,
          "finding": "Available explanation adequately describes the limited tasks and major interpretation caveats. Technical reproducibility and precision documentation remain incomplete."
        }
      ],
      "documented_problems": [
        {
          "ids": ["3.2", "6.3.2", "10.4.3"],
          "finding": "The paper gives examples where missing commas or valid related rules absent from supplied answers affect credit. These are documented threats to interpreting marking as engineering understanding."
        },
        {
          "ids": ["2.5", "3.2", "10.2.2"],
          "finding": "Equal task-group weighting combines different metrics and very unequal question counts. No evidence establishes that the resulting overall score or group scores measure distinct underlying skills."
        },
        {
          "ids": ["2.8", "6.2.4", "11.1.2"],
          "finding": "Systems receive different information supplies. Results therefore compare AI-plus-information arrangements, requiring that qualification when comparing scores."
        },
        {
          "ids": ["6.1.3.3", "10.1"],
          "finding": "Content uses one rulebook and a restricted task range. Manual review excludes some derived questions and explanations; explanations received a more limited consistency check."
        },
        {
          "ids": ["9.3", "9.7"],
          "finding": "Five passage sets were used with one AI, so that analysis does not isolate repeatability under identical conditions. In the 16-question performance group, one answer changes accuracy by 6.25 percentage points."
        },
        {
          "ids": ["10.4.3"],
          "rating": 1,
          "finding": "The described scale-bar drawings all comply with the rule, allowing an always-yes strategy to obtain their yes/no credit. Together with documented wording effects, this is inadequate evidence for attributing those credits specifically to engineering understanding. No claim is made that a tested AI used this strategy."
        },
        {
          "ids": ["5.1", "6.2.4", "6.3.1"],
          "finding": "Historical code, settings and inputs are not fully linked to every reported result. One released answer file has fewer rows than the paper's corresponding question count."
